INSERT INTO material_translations (material_id, locale, title, description, body) VALUES ('a1000000-0000-4000-8000-000000000005','ro','Pământul (caracteristici) — galerie foto','Galerie foto pentru lecția despre caracteristicile fizice și chimice ale Pământului.','{"captions":["Pământul – elipsoid de rotație, turtit la poli și bombat la Ecuator","Geoid, elipsoid și suprafața reală a Pământului","Geoidul – model exagerat al abaterilor față de elipsoid","Înclinarea axei Pământului (circa 23 grade și jumătate)","Gravitația terestră","Câmpul magnetic și polii magnetici ai Pământului","Magnetosfera și vântul solar","Aurore polare","Paleomagnetismul – inversările câmpului magnetic","Structura internă a Pământului: scoarță, manta, nucleu","Creșterea densității spre interiorul Pământului"]}');
